(function patchHomepage(){const lf=document.createElement('link');lf.rel='stylesheet';lf.href='https://fonts.googleapis.com/css2?family=Lateef:wght@400;500;600;700;800&display=swap';document.head.appendChild(lf);const st=document.createElement('style');st.textContent=`.finder-help{display:flex!important;align-items:center!important;gap:8px!important;flex-wrap:wrap}.finder-help>span{flex:0 0 36px;height:28px;display:flex;align-items:center;font-size:12px!important}.finder-example{height:28px;display:inline-flex;align-items:center;line-height:1;font-size:12px!important}.surah-section-head{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:14px}.surah-section-tools{display:flex;align-items:center;gap:14px}.surah-count{font-size:12px;color:#6b7280;white-space:nowrap}.filter-wrap{position:relative;display:inline-flex;align-items:center}.filter-wrap .filter{appearance:none;-webkit-appearance:none;min-width:118px;height:36px;padding:0 34px 0 12px;border-radius:8px}.filter-chevron{position:absolute;right:10px;width:16px;height:16px;pointer-events:none;color:#6b7280}.arabic,.result-arabic{font-family:Lateef,serif!important;font-size:31px!important;line-height:1.05!important;font-weight:600}.finder-status,.result-head,.result-sub,.result-type,.api-note,.journey span,.ad-label{font-size:12px!important}@media(max-width:900px){.surah-section-head{align-items:flex-start;flex-direction:column;gap:10px}.surah-section-tools{width:100%;justify-content:space-between}}`;document.head.appendChild(st);const quick=[...document.querySelectorAll('.section')].find(x=>x.querySelector('.section-heading')?.textContent.trim()==='Akses Cepat');if(quick)quick.remove();const sec=document.getElementById('surahListSection');if(sec){const heading=sec.querySelector('.section-heading'),row=sec.querySelector('.tabs-row'),count=document.getElementById('surahCount'),filter=document.getElementById('filter');if(heading&&row&&count&&filter){const head=document.createElement('div');head.className='surah-section-head';const tools=document.createElement('div');tools.className='surah-section-tools';count.className='surah-count';const fw=document.createElement('div');fw.className='filter-wrap';filter.parentNode.insertBefore(fw,filter);fw.appendChild(filter);const ico=document.createElement('i');ico.setAttribute('data-lucide','chevron-down');ico.className='filter-chevron';fw.appendChild(ico);tools.appendChild(count);tools.appendChild(fw);head.appendChild(heading);head.appendChild(tools);sec.insertBefore(head,row);row.remove()}}})();
const API='https://equran.id/api/v2';let surahs=[],shown=12;function normalizeSurah(x){return [x.nomor,x.namaLatin,x.arti,x.nama,`${x.jumlahAyat} Ayat · ${String(x.tempatTurun||'').toLowerCase()==='mekah'?'Makkiyah':'Madaniyah'}`]}function card(s){return `<a class="surah" href="surah-v4.html?surah=${s[0]}"><div class="num">${String(s[0]).padStart(2,"0")}</div><div><h4>${s[1]}</h4><div class="meaning">${s[2]}</div><div class="meta">${s[4]}</div></div><div class="arabic">${s[3]}</div></a>`}function renderList(list){const visible=list.slice(0,shown);surahGrid.innerHTML=visible.length?visible.map(card).join(''):'<div class="surah-loading">Surah tidak ditemukan.</div>';surahCount.textContent=`${list.length} surah`;loadBtn.classList.toggle('hidden',shown>=list.length);lucide.createIcons()}async function loadSurahs(){try{const r=await fetch(`${API}/surat`);if(!r.ok)throw new Error('API');const j=await r.json();surahs=(j.data||[]).map(normalizeSurah);renderList(surahs)}catch(e){surahs=[[1,'Al-Fatihah','Pembukaan','الفاتحة','7 Ayat · Makkiyah'],[2,'Al-Baqarah','Sapi','البقرة','286 Ayat · Madaniyah'],[18,'Al-Kahf','Gua','الكهف','110 Ayat · Makkiyah'],[36,'Yasin','Yasin','يس','83 Ayat · Makkiyah'],[55,'Ar-Rahman','Yang Maha Pengasih','الرحمن','78 Ayat · Madaniyah'],[56,"Al-Waqi'ah",'Hari Kiamat','الواقعة','96 Ayat · Makkiyah'],[67,'Al-Mulk','Kerajaan','الملك','30 Ayat · Makkiyah']];renderList(surahs);surahCount.textContent='API sedang tidak tersedia'} }function filtered(){const f=filter.value;return f==='Semua'?surahs:surahs.filter(s=>s[4].includes(f))}function loadMore(){shown+=12;renderList(filtered())}filter.onchange=()=>{shown=12;renderList(filtered())};function goSurah(id,ayat){location.href=ayat?`ayat-v5.html?surah=${id}&ayat=${ayat}`:`surah-v4.html?surah=${id}`}function openLastRead(){const x=JSON.parse(localStorage.getItem('l6q-last')||'null');goSurah(x?.surah||2,x?.ayat||1)}function updateLastReadLabel(){const x=JSON.parse(localStorage.getItem('l6q-last')||'null');if(x)lastReadText.textContent=`${x.name||'Surah'} · Ayat ${x.ayat||1}`}function setQuery(q){searchInput.value=q;runSearch()}document.querySelectorAll('.finder-example').forEach(b=>b.onclick=()=>setQuery(b.dataset.q));searchBtn.onclick=runSearch;searchInput.addEventListener('keydown',e=>{if(e.key==='Enter')runSearch()});function localMatches(q){q=q.toLowerCase();return surahs.filter(s=>`${s[0]} ${s[1]} ${s[2]} ${s[3]}`.toLowerCase().includes(q)).slice(0,6)}function showLocal(items,q){searchResults.classList.add('show');searchResults.innerHTML=`<div class="result-head"><span>Surah yang cocok</span><span>${items.length} hasil</span></div>`+items.map(s=>`<div class="result-item" onclick="goSurah(${s[0]})"><div><div class="result-title">${s[1]}</div><div class="result-sub">${s[2]} · ${s[4]}</div></div><div class="result-arabic">${s[3]}</div></div>`).join('')}async function runSearch(){const q=searchInput.value.trim();if(!q)return;const ref=q.match(/^\s*(\d{1,3})\s*[:.]\s*(\d{1,3})\s*$/);if(ref){goSurah(+ref[1],+ref[2]);return}const local=localMatches(q);if(local.length){showLocal(local,q);return}searchResults.classList.add('show');searchResults.innerHTML='<div class="finder-status">Mencari ayat dan tafsir yang paling relevan...</div>';try{const r=await fetch('https://equran.id/api/vector',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:q,limit:6,types:['ayat','tafsir'],minScore:.25})});if(!r.ok)throw new Error('search');const j=await r.json();const rows=j.hasil||[];searchResults.innerHTML=`<div class="result-head"><span>Hasil untuk “${escapeHtml(q)}”</span><span>${rows.length} hasil</span></div>`+(rows.length?rows.map(resultRow).join(''):'<div class="finder-status">Belum menemukan hasil. Coba kata yang lebih sederhana.</div>')}catch(e){searchResults.innerHTML='<div class="finder-status">Pencarian topik sedang tidak tersedia. Anda tetap dapat mencari berdasarkan nama atau nomor surah.</div>'}}function escapeHtml(x){return x.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function resultRow(x){const d=x.data||{},sid=d.id_surat||d.nomor_surat,ay=d.nomor_ayat||d.ayat;const title=x.tipe==='tafsir'?`Tafsir ${d.nama_surat||'Surah'} · Ayat ${ay}`:`${d.nama_surat||'Surah'} · Ayat ${ay}`;const sub=x.tipe==='tafsir'?(d.isi||''):(d.terjemahan_id||d.teks_latin||'');const ar=d.teks_arab||'';return `<div class="result-item" onclick="goSurah(${sid},${ay})"><div><div class="result-title">${escapeHtml(title)}</div><div class="result-sub">${escapeHtml(String(sub).slice(0,180))}</div></div><div>${ar?`<div class="result-arabic">${ar}</div>`:''}<div class="result-type">${x.tipe||'ayat'}</div></div></div>`}loadSurahs();updateLastReadLabel();const pop=["DPR Pertanyakan Kesiapan Anggaran Terkait Putusan MK Gratiskan SD-SMP","Gelombang Tinggi Pesisir Selatan Banten Capai 4 Meter, BMKG Minta Warga Waspada","Prediksi Harga Emas 2 Juni 2025, Siap-Siap Melesat","DPR Pertanyakan Kesiapan Anggaran Terkait Putusan MK Gratiskan SD-SMP","Wakil Ketua MPR Tegaskan Perusahaan Tambang yang Rusak Kawasan Wisata Harus Di-blacklist Selamanya"];popular.innerHTML=Array.from({length:10},(_,i)=>`<div class="popular-item"><div class="rank">${i+1}</div><div class="popular-copy"><b>${pop[i%5]}</b><span class="timeago">5 menit lalu</span></div></div>`).join("");const news=["Prediksi Harga Emas 2 Juni 2025, Siap-Siap Melesat","Momen Tak Terlihat dari Sidang Paripurna: Ekspresi, Gestur, dan Drama di Balik Mikrofon","Kemensos Salurkan Bantuan ke Korban Banjir di Demak, Ini Rinciannya"];latest.innerHTML=Array.from({length:9},(_,i)=>`<div class="latest-item"><span class="timeago">5 menit lalu</span><b>${news[i%3]}</b></div>`).join("");const header=document.querySelector('.header'),channelNav=document.querySelector('.channel-nav'),headerSpacer=document.getElementById('headerSpacer');let lastY=window.scrollY;function setScrollHeader(){const y=window.scrollY,goingUp=y<lastY;if(y<=8){header.classList.remove('is-returning');channelNav.classList.remove('is-sticky');headerSpacer.classList.remove('active')}else if(goingUp){channelNav.classList.remove('is-sticky');header.classList.add('is-returning');headerSpacer.classList.add('active')}else{header.classList.remove('is-returning');headerSpacer.classList.remove('active');if(y>128)channelNav.classList.add('is-sticky')}lastY=Math.max(y,0)}window.addEventListener('scroll',setScrollHeader,{passive:true});setScrollHeader();lucide.createIcons();